insert into members (id, name, title, description, sort_order, cover_id, status)
select (r->>'id')::uuid as id,
       nullif(r->>'name','') as name,
       nullif(r->>'title','') as title,
       nullif(r->>'description','') as description,
       nullif(r->>'sort_order','')::int as sort_order,
       nullif(r->>'cover_id','') as cover_id,
       coalesce(nullif(r->>'status',''),'draft')::content_status as status
